import { useMemo, useState } from 'react'
import { categories, initialOrders, initialProducts } from './data.js'

const money = (value) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(value)
const demoAccounts = {
  customer: { name: 'Valentina Rojas', email: 'cliente@novasale.co', password: 'Cliente123', role: 'customer' },
  admin: { name: 'Camila Torres', email: 'admin@novasale.co', password: 'Admin123', role: 'admin' },
}

function NovaMark() {
  return <svg aria-hidden="true" className="nova-mark" viewBox="0 0 24 24" fill="none"><path d="M4.5 19V5h3.4l8.2 8.1V5h3.4v14h-3.4L7.9 10.9V19H4.5Z" fill="currentColor" /><path d="M16.1 5h3.4v3.4h-3.4z" fill="#4D91FF" /></svg>
}

function Icon({ name, size = 19 }) {
  const paths = {
    search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-4-4" /></>,
    bag: <><path d="M5 8h14l1 13H4L5 8Z" /><path d="M9 9V6a3 3 0 0 1 6 0v3" /></>,
    user: <><circle cx="12" cy="8" r="4" /><path d="M4 21a8 8 0 0 1 16 0" /></>,
    heart: <path d="M20.8 8.8c0 4.1-8.8 10-8.8 10s-8.8-5.9-8.8-10a4.5 4.5 0 0 1 8.8-1.3 4.5 4.5 0 0 1 8.8 1.3Z" />,
    arrow: <><path d="M5 12h14" /><path d="m13 6 6 6-6 6" /></>,
    close: <><path d="m18 6-12 12M6 6l12 12" /></>,
    plus: <><path d="M12 5v14M5 12h14" /></>,
    minus: <path d="M5 12h14" />,
    check: <path d="m5 12 4 4L19 6" />,
    menu: <><path d="M4 7h16M4 12h16M4 17h16" /></>,
    box: <><path d="m12 3 9 5-9 5-9-5 9-5Z" /><path d="m3 8 9 5 9-5M3 8v9l9 5 9-5V8M12 13v9" /></>,
    chart: <><path d="M4 19V5M4 19h16" /><path d="m7 15 4-4 3 2 5-7" /></>,
    grid: <><rect x="4" y="4" width="6" height="6" rx="1" /><rect x="14" y="4" width="6" height="6" rx="1" /><rect x="4" y="14" width="6" height="6" rx="1" /><rect x="14" y="14" width="6" height="6" rx="1" /></>,
    logout: <><path d="M10 17l5-5-5-5M15 12H3" /><path d="M12 3h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7" /></>,
    shield: <><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z" /><path d="m9 12 2 2 4-4" /></>,
    truck: <><path d="M3 6h11v12H3zM14 10h4l3 3v5h-7z" /><circle cx="7.5" cy="18.5" r="1.5" /><circle cx="17.5" cy="18.5" r="1.5" /></>,
    spark: <><path d="m12 3 1.9 5.8L20 11l-6.1 2.1L12 19l-1.9-5.9L4 11l6.1-2.2L12 3Z" /><path d="m19 14 1 2.5 2 1-2 1-1 2.5-1-2.5-2-1 2-1 1-2.5Z" /></>,
  }
  return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{paths[name] || paths.spark}</svg>
}

function App() {
  const [screen, setScreen] = useState('shop')
  const [adminTab, setAdminTab] = useState('dashboard')
  const [activeNav, setActiveNav] = useState('Inicio')
  const [products, setProducts] = useState(initialProducts)
  const [orders, setOrders] = useState(initialOrders)
  const [cart, setCart] = useState({})
  const [favorites, setFavorites] = useState([])
  const [user, setUser] = useState(null)
  const [registeredAccounts, setRegisteredAccounts] = useState([])
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('Todas')
  const [sort, setSort] = useState('featured')
  const [maxPrice, setMaxPrice] = useState(700000)
  const [authError, setAuthError] = useState('')
  const [toast, setToast] = useState('')
  const [checkoutForm, setCheckoutForm] = useState({ address: '', city: '', payment: 'Tarjeta débito / crédito' })
  const [lastOrder, setLastOrder] = useState(null)
  const [showProductForm, setShowProductForm] = useState(false)
  const [mobileMenu, setMobileMenu] = useState(false)
  const [checkoutAfterLogin, setCheckoutAfterLogin] = useState(false)

  const cartItems = useMemo(() => Object.entries(cart).map(([id, quantity]) => ({ product: products.find((item) => item.id === Number(id)), quantity })).filter((item) => item.product), [cart, products])
  const itemCount = cartItems.reduce((sum, item) => sum + item.quantity, 0)
  const subtotal = cartItems.reduce((sum, item) => sum + item.product.price * item.quantity, 0)
  const shipping = subtotal === 0 || subtotal >= 250000 ? 0 : 12000
  const total = subtotal + shipping
  const visibleProducts = products.filter((product) => {
    const matchesQuery = `${product.name} ${product.category} ${product.description}`.toLowerCase().includes(query.toLowerCase())
    return matchesQuery && (category === 'Todas' || product.category === category) && product.price <= maxPrice
  }).sort((a, b) => sort === 'price-low' ? a.price - b.price : sort === 'price-high' ? b.price - a.price : sort === 'rating' ? b.rating - a.rating : 0)

  const notify = (message) => {
    setToast(message)
    window.setTimeout(() => setToast(''), 2600)
  }
  const goShop = () => { setScreen('shop'); setAdminTab('dashboard'); setCategory('Todas'); setActiveNav('Inicio'); setMobileMenu(false); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const goCatalog = (nav, selectedCategory = 'Todas') => {
    setActiveNav(nav)
    setCategory(selectedCategory)
    setScreen('shop')
    setMobileMenu(false)
    window.setTimeout(() => document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' }), 50)
  }
  const goAbout = () => { setActiveNav('Quiénes somos'); setScreen('about'); setMobileMenu(false); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const openLogin = () => { setAuthError(''); setScreen('login'); setMobileMenu(false); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const addToCart = (product) => {
    if (product.stock < 1) return notify('Este producto está agotado por ahora.')
    setCart((current) => ({ ...current, [product.id]: Math.min((current[product.id] || 0) + 1, product.stock) }))
    notify(`${product.name} se añadió a tu carrito`)
  }
  const setQuantity = (id, quantity) => {
    const stock = products.find((item) => item.id === id)?.stock || 0
    setCart((current) => {
      const next = { ...current }
      if (quantity < 1) delete next[id]
      else next[id] = Math.min(quantity, stock)
      return next
    })
  }
  const toggleFavorite = (id) => {
    setFavorites((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])
    notify(favorites.includes(id) ? 'Se quitó de tus favoritos' : 'Guardado en tus favoritos')
  }
  const openAdminTab = (tab) => { setAdminTab(tab); setScreen('admin'); setMobileMenu(false) }
  const demoLogin = (role) => {
    setAuthError('')
    const account = demoAccounts[role]
    setUser({ name: account.name, email: account.email, role: account.role })
    setScreen(role === 'admin' ? 'admin' : checkoutAfterLogin ? 'checkout' : 'account')
    if (role === 'customer') setCheckoutAfterLogin(false)
    if (role === 'admin') setCheckoutAfterLogin(false)
    if (role === 'admin') setAdminTab('dashboard')
    notify(`¡Hola, ${account.name.split(' ')[0]}! Sesión de demostración iniciada.`)
  }
  const handleLogin = (event) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const email = String(form.get('email')).trim().toLowerCase()
    const password = String(form.get('password'))
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return setAuthError('Escribe un correo electrónico válido.')
    if (password.length < 6) return setAuthError('La contraseña debe tener al menos 6 caracteres.')
    const account = [...Object.values(demoAccounts), ...registeredAccounts].find((candidate) => candidate.email.toLowerCase() === email && candidate.password === password)
    if (!account) return setAuthError('Correo o contraseña incorrectos. Revisa las credenciales de demostración.')
    setAuthError('')
    setUser({ name: account.name, email: account.email, role: account.role })
    if (account.role === 'admin') { setScreen('admin'); setAdminTab('dashboard') }
    else if (checkoutAfterLogin) { setScreen('checkout'); setCheckoutAfterLogin(false) }
    else setScreen('account')
    notify('¡Qué bueno tenerte de vuelta!')
  }
  const handleRegister = (event) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const name = String(form.get('name')).trim()
    const email = String(form.get('email')).trim()
    const password = String(form.get('password'))
    if (name.length < 2) return setAuthError('Escribe tu nombre completo.')
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return setAuthError('Escribe un correo electrónico válido.')
    if (password.length < 6) return setAuthError('La contraseña debe tener al menos 6 caracteres.')
    if (password !== form.get('confirm')) return setAuthError('Las contraseñas no coinciden.')
    if ([...Object.values(demoAccounts), ...registeredAccounts].some((account) => account.email.toLowerCase() === email.toLowerCase())) return setAuthError('Ya existe una cuenta con ese correo.')
    setRegisteredAccounts((current) => [...current, { name, email, password, role: 'customer' }])
    setUser({ name, email, role: 'customer' })
    setAuthError('')
    if (checkoutAfterLogin) { setScreen('checkout'); setCheckoutAfterLogin(false) }
    else setScreen('account')
    notify('Tu cuenta de demostración está lista. ¡Bienvenido a NovaSale!')
  }
  const signOut = () => { setUser(null); setScreen('shop'); notify('Cerraste sesión correctamente.') }
  const placeOrder = (event) => {
    event.preventDefault()
    if (!cartItems.length) return setScreen('shop')
    if (cartItems.some(({ product, quantity }) => product.stock < quantity)) return notify('El inventario cambió. Revisa las cantidades del carrito.')
    const order = { id: `NS-${1025 + orders.length - initialOrders.length}`, customer: user?.name || 'Valentina Rojas', date: 'Ahora', total, status: 'Pendiente', items: itemCount }
    setOrders((current) => [order, ...current])
    setProducts((current) => current.map((product) => ({ ...product, stock: product.stock - (cart[product.id] || 0) })))
    setLastOrder(order)
    setCart({})
    setScreen('success')
  }
  const updateStock = (id, amount) => setProducts((current) => current.map((product) => product.id === id ? { ...product, stock: Math.max(0, product.stock + amount) } : product))
  const createProduct = (event) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    setProducts((current) => [...current, { id: Date.now(), name: String(form.get('name')), category: String(form.get('category')), price: Number(form.get('price')), stock: Number(form.get('stock')), sku: `NS-${String(current.length + 1).padStart(3, '0')}`, rating: 5, reviews: 0, badge: 'Nuevo', emoji: '✨', color: 'lavender', description: 'Un nuevo favorito de NovaSale.' }])
    setShowProductForm(false)
    notify('Producto agregado al catálogo de demostración.')
  }

  const Header = () => <header className="store-header"><div className="header-inner">
    <button className="brand" onClick={goShop} aria-label="NovaSale, inicio"><span className="brand-mark"><NovaMark /></span><span>NOVA<span>SALE</span></span></button>
    <nav className={`main-nav ${mobileMenu ? 'nav-open' : ''}`} aria-label="Navegación principal">
      <button className={`nav-link ${activeNav === 'Inicio' ? 'active' : ''}`} onClick={goShop}>Inicio</button>
      <button className={`nav-link ${activeNav === 'Descubrir' ? 'active' : ''}`} onClick={() => goCatalog('Descubrir')}>Descubrir</button>
      <button className={`nav-link ${activeNav === 'Tecnología' ? 'active' : ''}`} onClick={() => goCatalog('Tecnología', 'Tecnología')}>Tecnología</button>
      <button className={`nav-link ${activeNav === 'Hogar' ? 'active' : ''}`} onClick={() => goCatalog('Hogar', 'Hogar')}>Hogar</button>
      <button className={`nav-link ${activeNav === 'Quiénes somos' ? 'active' : ''}`} onClick={goAbout}>Quiénes somos</button>
    </nav>
    <div className="header-actions">
      <label className="header-search"><Icon name="search" size={17} /><input value={query} onChange={(event) => { setQuery(event.target.value); if (screen !== 'shop') setScreen('shop') }} placeholder="Buscar productos" aria-label="Buscar productos" /></label>
      <button className="icon-button favorite-head" onClick={() => user ? setScreen('account') : openLogin()} aria-label="Mis favoritos"><Icon name="heart" /></button>
      <button className="icon-button cart-head" onClick={() => setScreen('cart')} aria-label={`Carrito, ${itemCount} productos`}><Icon name="bag" />{itemCount > 0 && <span className="cart-count">{itemCount}</span>}</button>
      {user ? <button className="user-chip" onClick={() => user.role === 'admin' ? openAdminTab('dashboard') : setScreen('account')}><span className="avatar">{user.name.charAt(0)}</span><span className="user-chip-name">{user.name.split(' ')[0]}</span></button> : <button className="button button-dark header-login" onClick={openLogin}>Ingresar <Icon name="arrow" size={16} /></button>}
      <button className="icon-button mobile-toggle" onClick={() => setMobileMenu((open) => !open)} aria-label="Abrir menú"><Icon name={mobileMenu ? 'close' : 'menu'} /></button>
    </div>
  </div></header>

  const ProductCard = ({ product }) => <article className="product-card" key={product.id}>
    <div className={`product-visual visual-${product.color}`}><span className="product-badge">{product.badge || 'Selección Nova'}</span><button className={`favorite-button ${favorites.includes(product.id) ? 'is-favorite' : ''}`} onClick={() => toggleFavorite(product.id)} aria-label={favorites.includes(product.id) ? 'Quitar de favoritos' : 'Agregar a favoritos'}><Icon name="heart" size={18} /></button><span className="product-emoji" role="img" aria-label={product.name}>{product.emoji}</span><span className="visual-caption">NOVA / SELECT</span></div>
    <div className="product-info"><div className="product-category">{product.category}<span>★ {product.rating} <small>({product.reviews})</small></span></div><h3>{product.name}</h3><p className="product-description">{product.description}</p><div className="product-buy"><div><strong>{money(product.price)}</strong>{product.oldPrice && <del>{money(product.oldPrice)}</del>}</div><button className="add-button" onClick={() => addToCart(product)} disabled={product.stock < 1} aria-label={`Añadir ${product.name} al carrito`}><Icon name="plus" size={18} /></button></div></div>
  </article>

  const Storefront = () => <><main>
    <section className="hero-shell"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot" /> TU NUEVA FORMA DE ELEGIR</div><h1>Encuentra eso<br />que <em>te mueve.</em></h1><p>Diseño, calidad y buenos hallazgos. Todo en un mismo lugar, pensado para tu día a día.</p><div className="hero-actions"><button className="button button-dark" onClick={() => document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' })}>Explorar colección <Icon name="arrow" size={17} /></button><span className="delivery-note"><span>✳</span> Envío gratis desde $250.000</span></div><div className="hero-proof"><div className="proof-avatars"><span>V</span><span>M</span><span>L</span><b>+</b></div><span><strong>4.9/5</strong><small> de compradores felices</small></span></div></div>
      <div className="hero-art"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><div className="hero-sun" /><div className="hero-object object-headphones">🎧</div><div className="hero-object object-watch">⌚</div><div className="hero-object object-lamp">💡</div><div className="hero-note note-top"><span>✦</span> Curado para ti</div><div className="hero-note note-bottom"><strong>01 — 08</strong><span>Pequeños cambios,<br />grandes favoritos.</span></div><span className="hero-sticker">NUEVA<br />TEMPORADA</span></div>
    </section>
    <section className="benefit-strip" aria-label="Beneficios de compra"><div><span className="benefit-icon">✦</span><span><strong>Selección con intención</strong><small>Productos que sí vas a usar</small></span></div><div><span className="benefit-icon">↗</span><span><strong>Envío a todo Colombia</strong><small>Gratis en compras desde $250.000</small></span></div><div><span className="benefit-icon">♡</span><span><strong>Compra sin complicaciones</strong><small>Fácil, segura y transparente</small></span></div></section>
    <section className="category-section content-width"><div className="section-heading"><div><span className="section-kicker">UN BUEN LUGAR PARA EMPEZAR</span><h2>Explora por categoría</h2></div><button className="text-link" onClick={() => { setCategory('Todas'); document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' }) }}>Ver todas <Icon name="arrow" size={16} /></button></div><div className="category-grid">{categories.map((item) => <button className={`category-card category-${item.tone}`} key={item.name} onClick={() => { setCategory(item.name); document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' }) }}><span className="category-symbol">{item.emoji}</span><span><strong>{item.name}</strong><small>{item.count} productos</small></span><span className="category-arrow"><Icon name="arrow" size={16} /></span></button>)}</div></section>
    <section className="catalog-section content-width" id="catalogo"><div className="section-heading catalog-heading"><div><span className="section-kicker">OBJETOS QUE HACEN LA DIFERENCIA</span><h2>Favoritos de la semana <span className="heading-spark">✳</span></h2><p>Una selección pequeña, pero muy bien pensada.</p></div><div className="catalog-sort"><label htmlFor="sort-products">Ordenar por</label><select id="sort-products" value={sort} onChange={(event) => setSort(event.target.value)}><option value="featured">Recomendados</option><option value="price-low">Menor precio</option><option value="price-high">Mayor precio</option><option value="rating">Mejor valorados</option></select></div></div>
      <div className="catalog-layout"><aside className="filter-panel"><div className="filter-title"><strong>Filtros</strong><button onClick={() => { setCategory('Todas'); setMaxPrice(700000); setQuery('') }}>Limpiar</button></div><div className="filter-group"><span className="filter-label">Categoría</span>{['Todas', ...categories.map((item) => item.name)].map((item) => <button key={item} className={`filter-option ${category === item ? 'selected' : ''}`} onClick={() => setCategory(item)}><span className="radio-dot" />{item}<small>{item === 'Todas' ? products.length : products.filter((product) => product.category === item).length}</small></button>)}</div><div className="filter-group price-filter"><span className="filter-label">Precio máximo</span><strong>{money(maxPrice)}</strong><input type="range" min="50000" max="700000" step="10000" value={maxPrice} onChange={(event) => setMaxPrice(Number(event.target.value))} aria-label="Precio máximo" /><div><small>$50.000</small><small>$700.000</small></div></div><div className="filter-help"><span>✦</span><p>¿No sabes qué elegir?</p><small>Nuestros favoritos son un buen comienzo.</small></div></aside>
        <div className="products-area"><div className="products-meta"><span>{visibleProducts.length} productos <span>·</span> {category === 'Todas' ? 'Todo lo bueno, en un solo lugar' : category}</span><div className="active-filter">{category !== 'Todas' && <button onClick={() => setCategory('Todas')}>{category} <Icon name="close" size={12} /></button>}</div></div>{visibleProducts.length ? <div className="products-grid">{visibleProducts.map((product) => ProductCard({ product }))}</div> : <div className="empty-results"><span>⌕</span><h3>No encontramos ese hallazgo</h3><p>Prueba con otra búsqueda o cambia los filtros.</p><button className="button button-outline" onClick={() => { setQuery(''); setCategory('Todas'); setMaxPrice(700000) }}>Limpiar filtros</button></div>}</div>
      </div>
    </section>
    <section className="newsletter content-width"><div className="newsletter-symbol">✳</div><div><span className="section-kicker">UNA NOTA DE VEZ EN CUANDO</span><h2>Buenas ideas, cero ruido.</h2><p>Novedades y hallazgos que sí vale la pena conocer.</p></div><form onSubmit={(event) => { event.preventDefault(); notify('¡Listo! Quedaste en la lista de novedades de demostración.'); event.currentTarget.reset() }}><label className="sr-only" htmlFor="newsletter-email">Tu correo electrónico</label><input id="newsletter-email" type="email" placeholder="Tu correo electrónico" required /><button className="button button-dark">Me interesa <Icon name="arrow" size={16} /></button></form></section>
  </main>{Footer({ setScreen, setAdminTab })}</>

  const Footer = ({ setScreen: changeScreen, setAdminTab: changeTab }) => <footer className="footer"><div className="footer-main"><div className="footer-brand"><button className="brand" onClick={goShop}><span className="brand-mark"><NovaMark /></span><span>nova<span>sale</span></span></button><p>Una tienda para las cosas<br />que hacen tu día mejor.</p></div><div><strong>Explora</strong><button onClick={goShop}>Inicio</button><button onClick={() => { changeScreen('shop'); window.setTimeout(() => document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' }), 50) }}>Productos</button><button onClick={() => changeScreen('about')}>Quiénes somos</button></div><div><strong>Tu espacio</strong><button onClick={() => changeScreen(user ? 'account' : 'login')}>Mis pedidos</button><button onClick={() => changeScreen('cart')}>Carrito</button><button onClick={() => changeScreen(user ? 'account' : 'login')}>Mi cuenta</button></div><div><strong>Modo demo</strong><button onClick={() => { if (user?.role === 'admin') { changeTab('dashboard'); changeScreen('admin') } else changeScreen('login') }}>Panel de administración</button><button onClick={() => changeScreen('architecture')}>Arquitectura visual</button><small>Frontend demostrativo · Datos ficticios</small></div></div><div className="footer-bottom"><span>© 2026 NovaSale. Hecho para elegir mejor.</span><span><Icon name="shield" size={14} /> Compra de demostración. Sin pagos reales.</span></div></footer>

  const CartScreen = () => <main className="page-shell content-width"><div className="breadcrumbs"><button onClick={goShop}>Inicio</button><span>/</span><span>Carrito</span></div><div className="page-title-row"><div><span className="section-kicker">CASI TUYO</span><h1>Tu carrito <span className="muted-count">({itemCount})</span></h1><p>Revisa tus hallazgos antes de confirmar.</p></div><button className="text-link" onClick={goShop}><span>←</span> Seguir explorando</button></div>{cartItems.length ? <div className="cart-layout"><section className="cart-list card-surface"><div className="cart-table-head"><span>Producto</span><span>Precio</span><span>Cantidad</span><span>Total</span><span /></div>{cartItems.map(({ product, quantity }) => <article className="cart-row" key={product.id}><div className="cart-product"><div className={`cart-thumb visual-${product.color}`}>{product.emoji}</div><div><small>{product.category}</small><strong>{product.name}</strong><button onClick={() => setQuantity(product.id, 0)}>Quitar</button></div></div><span className="cart-price">{money(product.price)}</span><div className="quantity-control"><button onClick={() => setQuantity(product.id, quantity - 1)} aria-label="Restar cantidad"><Icon name="minus" size={14} /></button><span>{quantity}</span><button onClick={() => setQuantity(product.id, quantity + 1)} disabled={quantity >= product.stock} aria-label="Aumentar cantidad"><Icon name="plus" size={14} /></button></div><strong className="cart-line-total">{money(product.price * quantity)}</strong><button className="remove-button" onClick={() => setQuantity(product.id, 0)} aria-label={`Quitar ${product.name}`}><Icon name="close" size={16} /></button></article>)}<div className="cart-bottom-note"><Icon name="truck" size={19} /><span>{subtotal >= 250000 ? '¡Tu compra tiene envío gratis!' : `Te faltan ${money(250000 - subtotal)} para obtener envío gratis.`}</span></div></section><aside className="order-sidebar">{OrderSummary({ subtotal, shipping, total, itemCount, onContinue: () => { if (!user) { setCheckoutAfterLogin(true); setScreen('login') } else setScreen('checkout') } })}<div className="trust-card card-surface"><h3><Icon name="shield" size={18} /> Compra protegida</h3><p><Icon name="check" size={15} /> Confirmación inmediata del pedido</p><p><Icon name="check" size={15} /> Seguimiento de tu entrega</p><p><Icon name="check" size={15} /> Tus datos siempre protegidos</p><div className="trust-payment"><span>VISA</span><span>MC</span><span>●●●</span><small>Pago simulado · sin cobros reales</small></div></div></aside></div> : <div className="empty-cart card-surface"><span className="empty-cart-icon"><Icon name="bag" size={34} /></span><h2>Tu carrito está tomando un descanso</h2><p>Hay cosas buenas esperándote en la tienda.</p><button className="button button-dark" onClick={goShop}>Explorar productos <Icon name="arrow" size={16} /></button></div>}</main>

  const OrderSummary = ({ subtotal: sub, shipping: delivery, total: amount, itemCount: count, onContinue }) => <div className="summary-card card-surface"><h2>Resumen del pedido</h2><p className="summary-items">{count} {count === 1 ? 'producto' : 'productos'} seleccionados</p><div className="summary-line"><span>Subtotal</span><strong>{money(sub)}</strong></div><div className="summary-line"><span>Envío</span><strong className={delivery === 0 ? 'free-shipping' : ''}>{delivery === 0 ? 'Gratis' : money(delivery)}</strong></div><div className="summary-line"><span>Impuestos</span><strong>Incluidos</strong></div><div className="summary-total"><span>Total</span><strong>{money(amount)}</strong></div><button className="button button-dark summary-cta" onClick={onContinue} disabled={!count}>Continuar al pago <Icon name="arrow" size={17} /></button><div className="summary-secure"><Icon name="shield" size={15} /> Pago de demostración, sin cobros reales</div></div>

  const AuthScreen = ({ register = false }) => <main className="auth-page"><div className="auth-art"><button className="brand auth-brand" onClick={goShop}><span className="brand-mark"><NovaMark /></span><span>nova<span>sale</span></span></button><div className="auth-art-content"><span className="auth-mini-label">UN LUGAR PARA ELEGIR MEJOR</span><h2>Las cosas buenas<br />empiezan con un<br /><em>hola.</em></h2><p>Encuentra tus favoritos y disfruta una experiencia de compra más simple.</p><div className="auth-art-objects"><span>🎧</span><span>💡</span><span>⌚</span><b>✳</b></div></div><span className="auth-legal">NovaSale · Diseño para la vida real</span></div><div className="auth-content"><button className="back-link" onClick={goShop}>← Volver a la tienda</button><div className="auth-form-wrap"><span className="section-kicker">{register ? 'EMPIEZA POR AQUÍ' : 'QUÉ BUENO VERTE'}</span><h1>{register ? 'Crea tu cuenta' : 'Inicia sesión'}</h1><p className="auth-subtitle">{register ? 'Guarda tus favoritos y sigue cada pedido.' : 'Entra a tu espacio NovaSale.'}</p><form className="auth-form" onSubmit={register ? handleRegister : handleLogin} noValidate>{register && <label>Nombre completo<input name="name" type="text" placeholder="Ej. Valentina Rojas" required minLength="2" /></label>}<label>Correo electrónico<input name="email" type="email" placeholder="tu@correo.com" required /></label><label>Contraseña<input name="password" type="password" placeholder="Mínimo 6 caracteres" required minLength="6" /></label>{register && <label>Confirma tu contraseña<input name="confirm" type="password" placeholder="Repite tu contraseña" required minLength="6" /></label>}{!register && <div className="auth-form-extra"><label className="remember-option"><input type="checkbox" defaultChecked /> Mantener sesión</label><button type="button" onClick={() => notify('Para esta demo, usa una de las cuentas de prueba de abajo.')}>¿Olvidaste tu contraseña?</button></div>}{authError && <p className="form-error" role="alert">{authError}</p>}<button className="button button-dark auth-submit">{register ? 'Crear mi cuenta' : 'Ingresar a mi cuenta'} <Icon name="arrow" size={17} /></button></form><div className="auth-switch">{register ? '¿Ya tienes una cuenta?' : '¿Aún no tienes cuenta?'} <button onClick={() => { setAuthError(''); setScreen(register ? 'login' : 'register') }}>{register ? 'Inicia sesión' : 'Regístrate'}</button></div><div className="demo-access"><span className="demo-label">ACCESO RÁPIDO DE DEMOSTRACIÓN</span><button onClick={() => demoLogin('customer')}><span className="demo-avatar">V</span><span><strong>Entrar como cliente</strong><small>cliente@novasale.co · Clave: Cliente123</small></span><Icon name="arrow" size={16} /></button><button onClick={() => demoLogin('admin')}><span className="demo-avatar demo-admin">C</span><span><strong>Entrar como administrador</strong><small>admin@novasale.co · Clave: Admin123</small></span><Icon name="arrow" size={16} /></button><p>Cuentas ficticias · acceso local de demostración</p></div></div></div></main>

  const CheckoutScreen = () => <main className="page-shell content-width"><div className="breadcrumbs"><button onClick={goShop}>Inicio</button><span>/</span><button onClick={() => setScreen('cart')}>Carrito</button><span>/</span><span>Finalizar compra</span></div><div className="page-title-row"><div><span className="section-kicker">UN ÚLTIMO PASO</span><h1>Finalizar compra</h1><p>Todo listo para que tus hallazgos lleguen a casa.</p></div><div className="checkout-steps"><span className="step-done"><b>✓</b> Carrito</span><i /><span className="step-current"><b>2</b> Envío y pago</span><i /><span><b>3</b> Confirmación</span></div></div><form className="checkout-layout" onSubmit={placeOrder}><div className="checkout-main"><section className="form-card card-surface"><div className="form-section-title"><span className="number-bubble">01</span><div><h2>¿A dónde lo enviamos?</h2><p>El envío es simulado para esta experiencia.</p></div></div><div className="checkout-fields"><label className="field-wide">Dirección<input required minLength="5" placeholder="Calle 00 # 00 - 00, apartamento" value={checkoutForm.address} onChange={(e) => setCheckoutForm({ ...checkoutForm, address: e.target.value })} /></label><label>Ciudad<input required placeholder="Bogotá D.C." value={checkoutForm.city} onChange={(e) => setCheckoutForm({ ...checkoutForm, city: e.target.value })} /></label><label>Departamento<select required defaultValue="Cundinamarca"><option>Bogotá D.C.</option><option>Cundinamarca</option><option>Antioquia</option><option>Valle del Cauca</option><option>Atlántico</option><option>Santander</option></select></label></div></section><section className="form-card card-surface"><div className="form-section-title"><span className="number-bubble">02</span><div><h2>Elige cómo pagar</h2><p>No se procesará ningún pago real.</p></div></div><div className="payment-options">{['Tarjeta débito / crédito', 'PSE · Débito bancario', 'Pago contra entrega'].map((method, index) => <label className="payment-option" key={method}><input type="radio" name="payment" value={method} checked={checkoutForm.payment === method} onChange={() => setCheckoutForm({ ...checkoutForm, payment: method })} /><span className="payment-option-icon">{['▤', '↗', '◷'][index]}</span><span><strong>{method}</strong><small>{['Visa, Mastercard y más', 'Tu banco de confianza', 'Pagas cuando lo recibas'][index]}</small></span><span className="payment-radio" /></label>)}</div></section><div className="checkout-simulation"><Icon name="shield" size={18} /><p><strong>Experiencia de compra simulada.</strong> El pedido se guardará únicamente en esta sesión y no se realizarán cobros ni envíos reales.</p></div></div><aside className="order-sidebar"><div className="summary-card card-surface"><h2>Tu pedido</h2><div className="checkout-items">{cartItems.map(({ product, quantity }) => <div key={product.id} className="checkout-item"><div className={`checkout-thumb visual-${product.color}`}>{product.emoji}<span>{quantity}</span></div><span>{product.name}</span><strong>{money(product.price * quantity)}</strong></div>)}</div><div className="summary-line"><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div className="summary-line"><span>Envío</span><strong className={shipping === 0 ? 'free-shipping' : ''}>{shipping ? money(shipping) : 'Gratis'}</strong></div><div className="summary-total"><span>Total</span><strong>{money(total)}</strong></div><button className="button button-dark summary-cta" disabled={!cartItems.length}>Confirmar pedido <Icon name="arrow" size={17} /></button><button className="checkout-back" type="button" onClick={() => setScreen('cart')}>Volver al carrito</button></div></aside></form></main>

  const SuccessScreen = () => <main className="success-page content-width"><div className="success-card card-surface"><div className="success-check"><Icon name="check" size={32} /></div><span className="section-kicker">PEDIDO CONFIRMADO</span><h1>¡Gracias por elegir mejor!</h1><p>Tu pedido <strong>{lastOrder?.id}</strong> quedó registrado en esta demostración. No se realizó ningún cobro ni envío real.</p><div className="success-details"><div><small>Pedido</small><strong>{lastOrder?.id}</strong></div><div><small>Estado</small><strong className="status-pill status-pendiente">Pendiente</strong></div><div><small>Total</small><strong>{money(lastOrder?.total || 0)}</strong></div></div><div className="success-actions"><button className="button button-dark" onClick={() => setScreen('account')}>Ver mis pedidos <Icon name="arrow" size={16} /></button><button className="button button-outline" onClick={goShop}>Seguir explorando</button></div></div><div className="success-aside"><span>✳</span><h2>Una buena elección merece un buen día.</h2><p>Gracias por hacer parte de NovaSale.</p></div></main>

  const AccountScreen = () => <main className="page-shell content-width account-page"><div className="breadcrumbs"><button onClick={goShop}>Inicio</button><span>/</span><span>Mi cuenta</span></div><div className="account-welcome"><div><span className="section-kicker">TU ESPACIO PERSONAL</span><h1>Hola, {user?.name.split(' ')[0] || 'Valentina'} <span>✳</span></h1><p>Un resumen de tus compras y tus pequeños favoritos.</p></div><button className="button button-outline" onClick={signOut}><Icon name="logout" size={16} /> Cerrar sesión</button></div><div className="account-stats"><div className="account-stat card-surface"><span className="account-stat-icon">▤</span><div><small>Pedidos realizados</small><strong>{orders.filter((order) => order.customer === user?.name).length + 1}</strong></div></div><div className="account-stat card-surface"><span className="account-stat-icon">♡</span><div><small>Productos guardados</small><strong>{favorites.length}</strong></div></div><div className="account-stat card-surface"><span className="account-stat-icon">✦</span><div><small>Tu nivel</small><strong>Explorador <small>· Nova</small></strong></div></div></div><div className="account-content-grid"><section className="account-orders card-surface"><div className="dashboard-section-heading"><div><h2>Tu actividad reciente</h2><p>Pedidos y estados de compra</p></div><button className="text-link" onClick={() => notify('Estás viendo todos tus pedidos de demostración.')}>Ver todo <Icon name="arrow" size={14} /></button></div>{orders.slice(0, 4).map((order) => <div className="account-order" key={order.id}><span className="order-icon">▤</span><div><strong>{order.id}</strong><small>{order.date} · {order.items} {order.items === 1 ? 'producto' : 'productos'}</small></div><span className={`status-pill ${statusClass(order.status)}`}>{order.status}</span><strong>{money(order.total)}</strong></div>)}<button className="shop-more-link" onClick={goShop}>Descubrir nuevos favoritos <Icon name="arrow" size={15} /></button></section><section className="account-favorites card-surface"><div className="dashboard-section-heading"><div><h2>Guardados para después</h2><p>Tus favoritos de la tienda</p></div></div>{favorites.length ? <div className="favorite-list">{products.filter((product) => favorites.includes(product.id)).map((product) => <div className="favorite-item" key={product.id}><div className={`cart-thumb visual-${product.color}`}>{product.emoji}</div><div><strong>{product.name}</strong><small>{money(product.price)}</small></div><button onClick={() => addToCart(product)} aria-label="Añadir al carrito"><Icon name="plus" /></button></div>)}</div> : <div className="no-favorites"><span>♡</span><p>Guarda aquí lo que te guste.</p><small>Solo toca el corazón en cualquier producto.</small></div>}<button className="button button-outline favorite-explore" onClick={goShop}>Ver la tienda <Icon name="arrow" size={15} /></button></section></div></main>

  const AdminScreen = () => {
    const tabs = [{ id: 'dashboard', label: 'Resumen', icon: 'grid' }, { id: 'products', label: 'Productos', icon: 'box' }, { id: 'orders', label: 'Pedidos', icon: 'bag' }, { id: 'inventory', label: 'Inventario', icon: 'chart' }, { id: 'customers', label: 'Clientes', icon: 'user' }]
    const lowStock = products.filter((product) => product.stock <= 5)
    return <main className="admin-shell">
      <aside className="admin-sidebar">
        <button className="brand admin-brand" onClick={goShop}><span className="brand-mark"><NovaMark /></span><span>NOVA<span>SALE</span></span></button>
        <span className="admin-label">ESPACIO DE TRABAJO</span>
        <nav>{tabs.map((tab) => <button key={tab.id} className={adminTab === tab.id ? 'admin-nav active' : 'admin-nav'} onClick={() => setAdminTab(tab.id)}><Icon name={tab.icon} size={18} />{tab.label}{tab.id === 'inventory' && lowStock.length > 0 && <span className="nav-alert">{lowStock.length}</span>}</button>)}<span className="admin-label admin-label-lower">SISTEMA</span><button className="admin-nav" onClick={() => setScreen('architecture')}><Icon name="grid" size={18} />Arquitectura</button><button className="admin-nav" onClick={goShop}><Icon name="bag" size={18} />Ver tienda</button></nav>
        <div className="admin-sidebar-bottom"><div className="admin-user-card"><span className="avatar admin-avatar">{user?.name.charAt(0) || 'C'}</span><span><strong>{user?.name || 'Camila Torres'}</strong><small>Administradora</small></span><button onClick={signOut} aria-label="Cerrar sesión"><Icon name="logout" size={16} /></button></div><span className="demo-mode"><span /> Modo demostración</span></div>
      </aside>
      <div className="admin-main">
        <header className="admin-topbar"><div className="admin-breadcrumb"><button onClick={() => setAdminTab('dashboard')}>Panel</button><span>/</span><strong>{tabs.find((tab) => tab.id === adminTab)?.label || 'Arquitectura'}</strong></div><div className="admin-top-actions"><span className="live-tag"><i /> DATOS LOCALES</span><button className="admin-top-user" onClick={() => notify('Sesión de administración activa.')}><span className="avatar">{user?.name.charAt(0) || 'C'}</span><span>{user?.name || 'Camila Torres'}</span></button></div></header>
        <div className="admin-content">
          {adminTab === 'dashboard' && <><div className="admin-heading"><div><span className="section-kicker">RESUMEN DEL NEGOCIO · HOY</span><h1>Buenos días, {user?.name.split(' ')[0] || 'Camila'} <span>✳</span></h1><p>Este es el estado actual de NovaSale.</p></div><button className="button button-dark" onClick={() => { setAdminTab('products'); setShowProductForm(true) }}><Icon name="plus" size={17} /> Nuevo producto</button></div><div className="metric-grid"><Metric label="Ventas del mes" value="$12.450.000" change="+12,5%" detail="vs. mes anterior" icon="↗" tone="lavender" /><Metric label="Pedidos recibidos" value="320" change="+8,2%" detail="vs. mes anterior" icon="▤" tone="mint" /><Metric label="Productos activos" value={products.length + 142} change="+5,0%" detail="en el catálogo" icon="◇" tone="peach" /><Metric label="Clientes" value="850" change="+10,4%" detail="clientes registrados" icon="♡" tone="butter" /></div><div className="admin-dashboard-grid"><section className="admin-panel-card sales-chart"><div className="dashboard-section-heading"><div><h2>Así se mueve la tienda</h2><p>Ventas de los últimos 7 días</p></div><button className="chart-period" onClick={() => notify('Mostrando los últimos 7 días de datos locales.')}>Últimos 7 días⌄</button></div><div className="chart-value">$2.840.000 <span>+12,5%</span></div><div className="chart-area"><div className="chart-y-labels"><span>$3M</span><span>$2M</span><span>$1M</span><span>$0</span></div><div className="chart-plot"><div className="chart-grid-lines"><i /><i /><i /><i /></div><svg viewBox="0 0 600 190" preserveAspectRatio="none" role="img" aria-label="Gráfico local de ventas en aumento"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#9fc0f5" stopOpacity=".28" /><stop offset="100%" stopColor="#9fc0f5" stopOpacity="0" /></linearGradient></defs><path d="M0 148 C35 132 52 116 90 126 S145 142 180 104 S245 115 270 91 S330 120 362 68 S430 93 454 54 S518 71 550 34 S580 49 600 25 L600 190 L0 190Z" fill="url(#chartFill)" /><path d="M0 148 C35 132 52 116 90 126 S145 142 180 104 S245 115 270 91 S330 120 362 68 S430 93 454 54 S518 71 550 34 S580 49 600 25" fill="none" stroke="#2563eb" strokeWidth="3" vectorEffect="non-scaling-stroke" />{[[90,126],[180,104],[270,91],[362,68],[454,54],[550,34],[600,25]].map(([cx, cy]) => <circle key={cx} cx={cx} cy={cy} r="4" fill="#fff" stroke="#2563eb" strokeWidth="3" vectorEffect="non-scaling-stroke" />)}</svg><div className="chart-x-labels"><span>Lun</span><span>Mar</span><span>Mié</span><span>Jue</span><span>Vie</span><span>Sáb</span><span>Dom</span></div></div></div></section><section className="admin-panel-card recent-orders"><div className="dashboard-section-heading"><div><h2>Pedidos recientes</h2><p>Últimas compras registradas</p></div><button className="mini-arrow" onClick={() => setAdminTab('orders')} aria-label="Ver todos los pedidos"><Icon name="arrow" size={17} /></button></div><div className="recent-list">{orders.slice(0, 4).map((order) => <button key={order.id} className="recent-order-row" onClick={() => setAdminTab('orders')}><span className="recent-order-icon">▤</span><span className="recent-order-info"><strong>{order.id}</strong><small>{order.customer}</small></span><span className={`status-pill ${statusClass(order.status)}`}>{order.status}</span><strong>{money(order.total)}</strong></button>)}</div><button className="view-all-button" onClick={() => setAdminTab('orders')}>Ver todos los pedidos <Icon name="arrow" size={14} /></button></section></div><section className="admin-panel-card inventory-alert"><div className="alert-icon"><Icon name="box" size={20} /></div><div className="inventory-alert-copy"><h2>Alertas de inventario</h2><p>{lowStock.length} productos necesitan atención por bajo stock.</p></div><div className="low-stock-items">{lowStock.slice(0, 3).map((product) => <button key={product.id} onClick={() => setAdminTab('inventory')}><span className={`mini-product visual-${product.color}`}>{product.emoji}</span><span><strong>{product.name}</strong><small>{product.sku}</small></span><b className="stock-warning">{product.stock} und.</b></button>)}</div><button className="text-link" onClick={() => setAdminTab('inventory')}>Revisar inventario <Icon name="arrow" size={15} /></button></section><div className="admin-bottom-note"><span>✳</span> Cifras y operaciones simuladas con datos locales de demostración.</div></>}
      {adminTab === 'products' && <><div className="admin-heading"><div><span className="section-kicker">CATÁLOGO DE NOVASALE</span><h1>Productos <span className="muted-count">({products.length})</span></h1><p>Gestiona lo que tus clientes pueden descubrir.</p></div><button className="button button-dark" onClick={() => setShowProductForm(true)}><Icon name="plus" size={17} /> Nuevo producto</button></div><section className="admin-panel-card table-card"><div className="table-toolbar"><span>Todos los productos <small>{products.length} artículos</small></span><label><Icon name="search" size={16} /><input placeholder="Buscar en catálogo" value={query} onChange={(event) => setQuery(event.target.value)} /></label></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Producto</th><th>SKU</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th></tr></thead><tbody>{products.filter((product) => product.name.toLowerCase().includes(query.toLowerCase())).map((product) => <tr key={product.id}><td><div className="table-product"><span className={`mini-product visual-${product.color}`}>{product.emoji}</span><strong>{product.name}</strong></div></td><td>{product.sku}</td><td>{product.category}</td><td>{money(product.price)}</td><td><strong className={product.stock <= 5 ? 'stock-warning' : ''}>{product.stock} und.</strong></td><td><span className={`status-pill ${product.stock > 0 ? 'status-entregado' : 'status-cancelado'}`}>{product.stock > 0 ? 'Activo' : 'Agotado'}</span></td></tr>)}</tbody></table></div><div className="table-foot">El catálogo se actualiza solo en esta sesión de demostración.</div></section></>}
      {adminTab === 'orders' && <><div className="admin-heading"><div><span className="section-kicker">ACTIVIDAD DE LA TIENDA</span><h1>Pedidos <span className="muted-count">({orders.length})</span></h1><p>Consulta las compras recientes de tus clientes.</p></div><button className="button button-outline" onClick={() => notify('Lista actualizada con datos de demostración.')}><Icon name="chart" size={16} /> Actualizar vista</button></div><section className="admin-panel-card table-card"><div className="table-toolbar"><span>Todos los pedidos <small>{orders.length} pedidos</small></span><button className="button button-outline button-small" onClick={() => notify('Los pedidos de esta demo se muestran por fecha.')}>Más recientes⌄</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Número de pedido</th><th>Cliente</th><th>Fecha</th><th>Productos</th><th>Total</th><th>Estado</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><strong>{order.id}</strong></td><td>{order.customer}</td><td>{order.date}</td><td>{order.items} {order.items === 1 ? 'producto' : 'productos'}</td><td><strong>{money(order.total)}</strong></td><td><select aria-label={`Estado de ${order.id}`} className="status-select" value={order.status} onChange={(event) => { setOrders((current) => current.map((item) => item.id === order.id ? { ...item, status: event.target.value } : item)); notify('Estado del pedido actualizado.') }}><option>Pendiente</option><option>Enviado</option><option>Entregado</option><option>Cancelado</option></select></td></tr>)}</tbody></table></div></section></>}
      {adminTab === 'inventory' && <><div className="admin-heading"><div><span className="section-kicker">CONTROL DE EXISTENCIAS</span><h1>Inventario <span className="muted-count">({products.reduce((sum, product) => sum + product.stock, 0)} und.)</span></h1><p>Ajusta existencias y detecta productos con bajo stock.</p></div><button className="button button-outline" onClick={() => notify('Inventario actualizado con los datos locales.')}>Actualizar inventario <Icon name="chart" size={16} /></button></div><div className="inventory-summary-row"><div className="inventory-summary card-surface"><span className="inv-summary-icon">▤</span><div><small>Productos en catálogo</small><strong>{products.length}</strong></div></div><div className="inventory-summary card-surface"><span className="inv-summary-icon inv-warning">!</span><div><small>Stock bajo · 5 o menos</small><strong>{lowStock.length}</strong></div></div><div className="inventory-summary card-surface"><span className="inv-summary-icon inv-empty">×</span><div><small>Sin existencias</small><strong>{products.filter((product) => product.stock === 0).length}</strong></div></div></div><section className="admin-panel-card table-card"><div className="table-toolbar"><span>Control de existencias <small>Ajustes de stock en vivo</small></span><label><Icon name="search" size={16} /><input placeholder="Buscar producto" value={query} onChange={(event) => setQuery(event.target.value)} /></label></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Producto</th><th>SKU</th><th>Stock disponible</th><th>Nivel de stock</th><th>Acción</th></tr></thead><tbody>{products.filter((product) => product.name.toLowerCase().includes(query.toLowerCase())).map((product) => <tr key={product.id}><td><div className="table-product"><span className={`mini-product visual-${product.color}`}>{product.emoji}</span><strong>{product.name}</strong></div></td><td>{product.sku}</td><td><strong className={product.stock <= 5 ? 'stock-warning' : ''}>{product.stock} unidades</strong></td><td><span className={`status-pill ${product.stock <= 5 ? 'status-pendiente' : 'status-entregado'}`}>{product.stock === 0 ? 'Agotado' : product.stock <= 5 ? 'Stock bajo' : 'Saludable'}</span></td><td><div className="stock-actions"><button onClick={() => updateStock(product.id, -1)} disabled={product.stock < 1} aria-label="Restar inventario"><Icon name="minus" size={14} /></button><button onClick={() => updateStock(product.id, 1)} aria-label="Sumar inventario"><Icon name="plus" size={14} /></button></div></td></tr>)}</tbody></table></div></section></>}
      {adminTab === 'customers' && <><div className="admin-heading"><div><span className="section-kicker">COMUNIDAD NOVASALE</span><h1>Clientes <span className="muted-count">(850)</span></h1><p>Personas que han elegido comprar mejor.</p></div><button className="button button-outline" onClick={() => notify('Los clientes de esta pantalla son ficticios.')}>Exportar lista <Icon name="arrow" size={15} /></button></div><section className="admin-panel-card table-card"><div className="table-toolbar"><span>Clientes recientes <small>Datos ficticios</small></span></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Cliente</th><th>Correo electrónico</th><th>Pedidos</th><th>Total comprado</th><th>Estado</th></tr></thead><tbody>{[['Valentina Rojas', 'valentina@email.com', 4, 939400], ['Mateo Gómez', 'mateo@email.com', 3, 1249500], ['Laura Méndez', 'laura@email.com', 2, 589800], ['Andrés Silva', 'andres@email.com', 5, 1539900], ['Sofía Pérez', 'sofia@email.com', 1, 219900]].map((customer, index) => <tr key={customer[1]}><td><div className="table-product"><span className="avatar customer-avatar">{customer[0].charAt(0)}</span><strong>{customer[0]}</strong></div></td><td>{customer[1]}</td><td>{customer[2]}</td><td><strong>{money(customer[3])}</strong></td><td><span className={`status-pill ${index === 2 ? 'status-pendiente' : 'status-entregado'}`}>{index === 2 ? 'Nuevo' : 'Activo'}</span></td></tr>)}</tbody></table></div></section></>}
      </div></div>{showProductForm && <div className="modal-backdrop" onClick={() => setShowProductForm(false)}><form className="product-modal card-surface" onSubmit={createProduct} onClick={(event) => event.stopPropagation()}><button className="modal-close" type="button" onClick={() => setShowProductForm(false)} aria-label="Cerrar"><Icon name="close" /></button><span className="section-kicker">GESTIÓN DE CATÁLOGO</span><h2>Nuevo producto</h2><p>Agrega un artículo a tu catálogo de demostración.</p><label>Nombre del producto<input name="name" required minLength="2" placeholder="Ej. Taza cerámica Aura" /></label><div className="modal-fields"><label>Categoría<select name="category"><option>Tecnología</option><option>Hogar</option><option>Moda</option><option>Deportes</option></select></label><label>Precio (COP)<input name="price" type="number" required min="1000" placeholder="89000" /></label></div><label>Stock inicial<input name="stock" type="number" required min="0" defaultValue="10" /></label><button className="button button-dark modal-submit">Agregar al catálogo <Icon name="arrow" size={16} /></button></form></div>}</main>
  }

  const Metric = ({ label, value, change, detail, icon, tone }) => <div className="metric-card"><div className={`metric-icon metric-${tone}`}>{icon}</div><span className="metric-label">{label}</span><strong className="metric-value">{value}</strong><span className="metric-change">↗ {change} <small>{detail}</small></span></div>
  const AboutScreen = () => <><main className="about-page content-width"><div className="breadcrumbs"><button onClick={goShop}>Inicio</button><span>/</span><span>Quiénes somos</span></div><section className="about-hero"><div><span className="section-kicker">UNA TIENDA CON OTRA IDEA</span><h1>Menos ruido.<br /><em>Mejores elecciones.</em></h1><p>NovaSale nace para hacer más fácil encontrar productos útiles, bien elegidos y con una experiencia de compra clara de principio a fin.</p><div className="about-actions"><button className="button button-dark" onClick={goShop}>Conocer la tienda <Icon name="arrow" size={16} /></button><button className="button button-outline" onClick={() => setScreen('architecture')}>Ver arquitectura</button></div></div><div className="about-art"><span className="about-star">✳</span><span className="about-object">🛍️</span><span className="about-art-note">Una mejor forma<br />de encontrar.</span></div></section><section className="about-values"><div className="section-heading"><div><span className="section-kicker">LO QUE NOS IMPORTA</span><h2>Comprar bien debería sentirse así.</h2></div></div><div className="about-value-grid"><article><span>✦</span><h3>Elegido con intención</h3><p>Un catálogo cuidado para que descubrir algo bueno sea sencillo.</p></article><article><span>↗</span><h3>Claro de principio a fin</h3><p>Precios, cantidades y resumen visibles antes de confirmar tu pedido.</p></article><article><span>♡</span><h3>Hecho para personas</h3><p>Una experiencia simple, accesible y fácil de recorrer en cualquier pantalla.</p></article></div></section><div className="about-demo-note"><Icon name="shield" size={18} /><p><strong>Proyecto demostrativo.</strong> NovaSale simula un comercio digital con datos ficticios y estado local; no procesa pagos ni conecta servicios reales.</p></div></main>{Footer({ setScreen, setAdminTab })}</>
  const ArchitectureScreen = () => {
    const serviceGroups = [
      [{ name: 'Autenticación', key: 'AUTH', icon: '◈', desc: 'Sesión y roles' }, { name: 'Usuarios', key: 'USER', icon: '♙', desc: 'Perfiles y cuentas' }, { name: 'Catálogo', key: 'CAT', icon: '▦', desc: 'Productos y categorías' }],
      [{ name: 'Inventario', key: 'STOCK', icon: '▤', desc: 'Existencias locales' }, { name: 'Pedidos', key: 'ORDER', icon: '▧', desc: 'Checkout y órdenes' }, { name: 'Pagos', key: 'PAY', icon: '◉', desc: 'Flujo visual simulado' }, { name: 'Logística', key: 'SHIP', icon: '↗', desc: 'Seguimiento de envío' }],
    ]
    return <main className="architecture-page content-width"><div className="breadcrumbs"><button onClick={goShop}>Inicio</button><span>/</span><span>Arquitectura</span></div><div className="architecture-heading"><div><span className="section-kicker">POR DENTRO DE NOVASALE</span><h1>Pequeños servicios.<br /><em>Una gran experiencia.</em></h1><p>Una representación visual de cómo se organizaría una plataforma comercial moderna. Aquí todo funciona en modo demostración, con datos ficticios y estado local.</p></div><div className="architecture-stamp"><Icon name="spark" size={28} /><span>SPA<br />DEMO</span></div></div><section className="architecture-board"><div className="architecture-layer-label"><span>01</span> CAPA DE PRESENTACIÓN <small>Lo que ves y usas</small></div><div className="frontend-nodes"><button className="arch-node frontend-node" onClick={goShop}><span className="arch-node-icon">◫</span><strong>NovaSale web app</strong><small>React · Interfaz de usuario</small><i>ACTIVO</i></button><div className="arch-arrow down-arrow">↓</div><span className="frontend-caption">Navegación · Búsqueda · Checkout · Panel</span></div><div className="architecture-layer-label gateway-label"><span>02</span> CAPA DE ENTRADA <small>Enrutamiento conceptual</small></div><button className="gateway-node" onClick={() => notify('API Gateway: nodo representativo, no conectado a un servicio real.')}><span className="gateway-icon">⌘</span><div><small>PUNTO DE ENTRADA</small><strong>API Gateway</strong><span>Ruteo conceptual · Control de acceso visual</span></div><span className="gateway-tag">DEMO LOCAL</span></button><div className="gateway-connectors"><i /><i /><i /><i /><i /><i /><i /></div><div className="architecture-layer-label services-label"><span>03</span> SERVICIOS DE DOMINIO <small>Módulos independientes</small></div><div className="service-groups">{serviceGroups.map((group, index) => <div className="service-row" key={index}>{group.map((service) => <button className="service-node" key={service.key} onClick={() => notify(`${service.name}: componente ilustrativo, sin integración real.`)}><span className="service-node-icon">{service.icon}</span><span className="service-node-key">{service.key}</span><strong>{service.name}</strong><small>{service.desc}</small><span className="service-dot" /></button>)}</div>)}</div><div className="services-to-data"><span>Persistencia lógica demostrativa · sin base de datos</span><i /><i /><i /></div><div className="architecture-layer-label data-label"><span>04</span> CAPA DE DATOS <small>Solo representación</small></div><div className="data-nodes"><div className="data-node"><span>▤</span><div><strong>Datos locales de sesión</strong><small>Catálogo · carrito · órdenes · inventario</small></div><span className="local-badge">EN MEMORIA</span></div><div className="data-node cache-node"><span>◌</span><div><strong>Estado de interfaz</strong><small>Filtros · navegación · cuenta demo</small></div><span className="local-badge">LOCAL</span></div></div></section><div className="architecture-legend"><span><i className="legend-indigo" /> Representación de componentes</span><span><i className="legend-green" /> Interacción local activa</span><span><i className="legend-gray" /> Sin conexión a servicios reales</span></div><div className="architecture-note"><span><Icon name="shield" size={20} /></span><p><strong>Esta vista es únicamente ilustrativa.</strong> No existe API Gateway, microservicio, base de datos, pasarela de pagos ni conexión de red implementada. Los controles solo presentan respuestas locales de demostración.</p><button className="button button-outline" onClick={goShop}>Volver a explorar <Icon name="arrow" size={15} /></button></div></main>
  }
  function statusClass(status) { return { Pendiente: 'status-pendiente', Enviado: 'status-enviado', Entregado: 'status-entregado', Cancelado: 'status-cancelado' }[status] || 'status-pendiente' }

  let content
  if (screen === 'shop') content = Storefront()
  else if (screen === 'cart') content = CartScreen()
  else if (screen === 'checkout') content = CheckoutScreen()
  else if (screen === 'success') content = SuccessScreen()
  else if (screen === 'account') content = AccountScreen()
  else if (screen === 'login') content = AuthScreen({})
  else if (screen === 'register') content = AuthScreen({ register: true })
  else if (screen === 'admin') content = AdminScreen()
  else if (screen === 'about') content = AboutScreen()
  else content = ArchitectureScreen()

  const adminMode = screen === 'admin'
  const authMode = screen === 'login' || screen === 'register'
  return <div className={adminMode ? 'app admin-app' : 'app'}>{!adminMode && !authMode && Header()}{content}{toast && <div className="toast" role="status"><span><Icon name="check" size={16} /></span>{toast}</div>}</div>
}

function statusClass(status) {
  return { Pendiente: 'status-pendiente', Enviado: 'status-enviado', Entregado: 'status-entregado', Cancelado: 'status-cancelado' }[status] || 'status-pendiente'
}

export default App
